\begin{ex}%[6H5N2]
\immini[thm]{
Tìm trục đối xứng và tâm đối xứng của hình ảnh sau
}{
\begin{tikzpicture}

    % Tâm đối xứng của hình
    \coordinate (O) at (0,0);

    % Vẽ các tam giác đối xứng qua tâm O
    \fill[blue!40] (0,0) -- (2,1) -- (1,2) -- cycle;  % Tam giác trên bên phải
    \fill[blue!40] (0,0) -- (2,-1) -- (1,-2) -- cycle;  % Tam giác dưới bên phải
    \fill[blue!40] (0,0) -- (-2,-1) -- (-1,-2) -- cycle;  % Tam giác dưới bên trái
    \fill[blue!40] (0,0) -- (-2,1) -- (-1,2) -- cycle;  % Tam giác trên bên trái

    % Vẽ đường viền cho các tam giác
    \draw[thick, blue!70] (0,0) -- (2,1) -- (1,2) -- cycle;
    \draw[thick, blue!70] (0,0) -- (2,-1) -- (1,-2) -- cycle;
    \draw[thick, blue!70] (0,0) -- (-2,-1) -- (-1,-2) -- cycle;
    \draw[thick, blue!70] (0,0) -- (-2,1) -- (-1,2) -- cycle;

    % Vẽ tâm đối xứng
    \fill[red] (O) circle(2pt);  % Tâm đối xứng màu đỏ

\end{tikzpicture}
}
\loigiai{
\begin{center}
\begin{tikzpicture}[scale=0.82, font=\footnotesize]
\coordinate (O) at (0,0);
\foreach \sx/\sy in {1/1, 1/-1, -1/-1, -1/1} {
  \fill[blue!35, draw=blue!70, thick] (0,0) -- (\sx*2,\sy*1) -- (\sx*1,\sy*2) -- cycle;
}
\draw[red, thick, dashed] (-2.3,0) -- (2.3,0) node[right] {$d_2$};
\draw[red, thick, dashed] (0,-2.3) -- (0,2.3) node[above] {$d_1$};
\draw[red, thick, dashed] (-2.1,-2.1) -- (2.1,2.1) node[above right] {$d_3$};
\draw[red, thick, dashed] (-2.1,2.1) -- (2.1,-2.1) node[below right] {$d_4$};
\fill[red] (O) circle (2.2pt) node[below left=2pt, red] {$O$};
\end{tikzpicture}
\end{center}
Hình gồm bốn tam giác bằng nhau xoay đều quanh tâm $O$:
\begin{itemize}
\item Hình có $4$ trục đối xứng là trục tung $d_1$, trục hoành $d_2$ và hai đường chéo $d_3, d_4$ đi qua $O$.
\item Hình có tâm đối xứng là điểm $O$ (giao điểm của $4$ trục đối xứng).
\end{itemize}
}\end{ex}
